    "Reduce the heat to low or remove the pan from the heat. Stir in the cheddar, American cheese, and cream cheese until melted and smooth. Season to taste with salt and pepper. Reserve a little cheese sauce for topping the burgers, then toss the cooked pasta with the remaining sauce. Keep warm over very low heat, stirring as needed; loosen with a splash of milk if it becomes too thick.",
    "Mix the beef gently with the seasoning salt, garlic powder, onion powder, and 1/2 teaspoon pepper. Divide into 8 equal portions and shape into thin patties, about 2 ounces each, for 2 patties per burger.",
    "Grill or pan-fry the patties over medium-high heat until browned and cooked through, turning as needed. Check that the center reaches 160°F with a food thermometer; cooking time depends on thickness and heat.",
    "Mix the softened 1/2 cup butter with the minced garlic and parsley. Spread onto the cut sides of the brioche rolls. Toast the buttered sides in a skillet over medium heat or briefly under the broiler until golden, watching closely so the garlic does not burn.",
    "Assemble each burger with 2 cooked patties, a generous spoonful of mac and cheese, and some reserved cheese sauce between the toasted garlic-butter brioche bun halves. Serve immediately, with any extra mac and cheese alongside.",
    "Notes",
    "The supplied description calls for two patties on each of four rolls, so the pound of beef is divided into 8 thin patties. One US stick of butter equals 1/2 cup (8 tablespoons); this is separate from the 2 tablespoons used in the cheese sauce.",
