    "id": "recipe-167",
    "title": "Taco Night Seasoning",
    "category": "Sauces, Dressings & Condiments",
    "lines": [
      "Practical batch recipe | Prep: about 5 minutes | Dry seasoning blend",
      "Ingredients",
      "2 tablespoons chili powder",
      "1 tablespoon ground cumin",
      "2 teaspoons paprika",
      "2 teaspoons garlic powder",
      "2 teaspoons onion powder",
      "1 teaspoon ground coriander",
      "1 teaspoon dried oregano (suggested amount)",
      "1 teaspoon salt, or to taste (suggested starting amount)",
      "1/2 teaspoon cayenne pepper",
      "Directions",
      "Measure all ingredients into a clean, completely dry bowl. Break up any powder or sugar lumps with a dry spoon.",
      "For herb blends, gently crumble large herb flakes and rosemary between your fingers or with a mortar and pestle if you prefer a finer texture.",
      "Whisk or stir thoroughly until evenly mixed.",
      "Transfer to a clean, dry, airtight jar. Label with the blend name and date. Shake or stir before each use.",
      "Store in a cool, dry, dark cupboard away from heat and steam. For best flavor, use within 3–6 months, or sooner if your starting spices are older.",
      "Notes",
      "The graphic does not specify oregano or salt amounts; those measurements are suggested starting points.",
      "Use commercially dried herbs and fully dried citrus zest for these pantry blends. Fresh zest or herbs add moisture and are not suitable for the stated dry-storage method.",
      "Keep measuring spoons dry. If a spoon touches raw meat, do not put it back in the jar.",
      "Suggested use: For a suggested starting ratio, brown 1 pound ground meat, drain excess fat, and stir in 1–2 tablespoons seasoning plus 1/4 cup water. Simmer until the meat is cooked through and the liquid reduces. Taste and adjust.",
      "Source",
      "Ingredient list adapted from the “8 Homemade Spice Blends” graphic supplied by Corey, labeled “Chef Hannah.” Missing or ambiguous quantities are identified above. Mixing directions and usage suggestions added for this website."
    ],
