    "Discard the bay leaves. Lift out the chicken and vegetables. Measure 2 cups of broth separately. Save or discard the rest; use only the measured broth in the loaf.",
    "Hydrate the gelatin according to its package, using part of the measured broth cooled first if the label calls for cold liquid. Stir into the remaining hot measured broth until dissolved.",
    "Blend the chicken, vegetables, cooked beets, Cajun seasoning, and gelatin broth until smooth. Use an immersion blender or a countertop blender approved for hot food, following its instructions.",
