const creamyGarlicChicken = {
  "id": "recipe-155",
  "title": "Creamy Garlic Chicken",
  "category": "Main Dishes",
  "lines": [
    "Practical batch recipe | Serves 4 | Prep: 5 minutes | Cook: about 25 minutes",
    "By Laura Sampson, Little House Big Alaska. Rated 5 out of 5 from 41 votes when checked.",
    "Ingredients",
    "1 pound chicken breasts, cut or pounded into four 1/2-inch-thick pieces",
    "1/4 cup all-purpose flour, for coating",
    "1 teaspoon salt",
    "1 teaspoon garlic powder",
    "1/4 teaspoon black pepper",
    "3 tablespoons oil",
    "3 tablespoons butter",
    "1 head garlic, peeled (about 12–15 cloves)",
    "1/3 cup all-purpose flour, for the gravy",
    "3 cups chicken broth",
    "1 teaspoon onion powder",
    "1/2 teaspoon ground mustard",
    "1 teaspoon Italian seasoning",
    "1/2 cup cream",
    "1/2 cup shredded Parmesan",
    "Directions",
    "Mix the coating flour, salt, garlic powder, and pepper. Dust both sides of the chicken with this mixture.",
    "Heat the oil in a skillet over medium-high. Fry the cutlets about 3–5 minutes per side, until golden and cooked through. Transfer to a plate and pour off excess oil.",
    "Lower the heat to medium-low. Add butter and garlic. Stir frequently until the garlic softens enough to crush, then mash the cloves in the pan.",
    "Stir in the gravy flour, onion powder, mustard, and Italian seasoning. Cook until golden, loosening the browned bits from the pan.",
    "Whisk in the broth gradually. Once the gravy bubbles, stir in the cream and Parmesan until smooth. Return the chicken to the sauce and warm through.",
    "Source",
    "Laura Sampson, Little House Big Alaska. Directions paraphrased for Corey’s Kitchen.",
    "https://littlehousebigalaska.com/2023/08/creamy-garlic-chicken.html"
  ]
};
