const $=s=>document.querySelector(s);let recipes=[],headings=new Set(),category='All recipes',cuisine='All cuisines',query='',onlyFav=false,sort='collection',current=null,serving='original';const favoriteStorageKey=window.coreysCloud?.userId?'coreys-favorites-account-'+window.coreysCloud.userId:'coreys-favorites';let saved=new Set();try{const ids=JSON.parse(localStorage.getItem(favoriteStorageKey)||'[]');if(Array.isArray(ids))saved=new Set(ids.filter(id=>typeof id==='string'&&/^recipe-[1-9]\d{0,5}$/.test(id)));}catch{}const palette=[['#e8e8cf','#6e8a4d'],['#f5d5bf','#dc7546'],['#e7dcf1','#87709b'],['#f5e4ac','#bb913c'],['#dbe7dd','#508575'],['#eecfca','#bc6b55']];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function art(r,i){if(recipePhotos[r.id])return `<div class="card-art food-photo"><img src="${recipePhotos[r.id]}.${Number(r.id.slice(7)) >= 172 && Number(r.id.slice(7)) <= 177 ? 'svg?v=party-dips-1' : r.id === 'recipe-139' ? 'svg' : r.id === 'recipe-137' ? 'svg' : r.id === 'recipe-136' ? 'svg?v=693dcbb' : 'webp'}" alt="Illustrative serving suggestion for ${esc(r.title)}" loading="lazy" width="1200" height="800"><span class="photo-badge">Serving inspiration</span></div>`;const [bg,accent]=palette[i%palette.length];const type=r.category;let bits='';const seed=r.title.split('').reduce((n,c)=>n+c.charCodeAt(0),0);for(let k=0;k<17;k++){const a=k*2.399+seed,x=120+Math.cos(a)*(15+(k%5)*9),y=83+Math.sin(a)*(10+(k%4)*8);const color=['#c65132','#e8bd60','#4a7951','#eee0b5',accent][k%5];bits+=`<ellipse cx="${x}" cy="${y}" rx="${k%3+5}" ry="${k%2+4}" fill="${color}" transform="rotate(${k*35} ${x} ${y})"/>`;}
let shape=type.includes('Beverages')?`<ellipse cx="120" cy="133" rx="43" ry="7" fill="#0001"/><path d="M85 54h65v63q-4 25-32 25t-33-25Z" fill="#fff8e9"/><path d="M150 65q39-3 29 29t-28 7" stroke="#fff8e9" stroke-width="10" fill="none"/><ellipse cx="117" cy="55" rx="32" ry="10" fill="#865d43"/><path d="M108 40q-12-14 2-24m18 24q-10-14 2-24" fill="none" stroke="#fff9e8" stroke-width="3"/>`:type.includes('Bread')||type.includes('Muffins')?`<ellipse cx="120" cy="134" rx="74" ry="11" fill="#0001"/><path d="M51 111q0-59 60-66t77 60v25H52Z" fill="#bb7e42"/><path d="M57 102q0-52 57-58t67 58Z" fill="#dba457"/><path d="m85 65-9 26m35-35-8 31m36-31-9 30" stroke="#f8dba2" stroke-width="6" stroke-linecap="round"/>`:type.includes('Cakes')?`<ellipse cx="120" cy="137" rx="77" ry="12" fill="#fff9eb"/><path d="M68 80h105v50H68Z" fill="#8e573d"/><path d="M68 96h105v12H68Z" fill="#edc59b"/><path d="M67 80q54-37 107 0v16q-7-9-13 0t-17 0-17 0-17 0-17 0-17 0-9 0Z" fill="#c6805b"/><circle cx="120" cy="61" r="9" fill="#bc4839"/>`:`<ellipse cx="120" cy="130" rx="83" ry="13" fill="#0001"/><ellipse cx="120" cy="88" rx="83" ry="55" fill="#fff8e7"/><ellipse cx="120" cy="85" rx="69" ry="43" fill="${type.includes('Soup')?'#d6ac69':'#dfcda0'}"/>${bits}<path d="M50 105q68 48 140 0" fill="none" stroke="#eee2c5" stroke-width="2"/>`;return `<div class="card-art" style="background:${bg}"><svg viewBox="0 0 240 170" aria-hidden="true">${shape}</svg></div>`;}
function favorite(id){if(saved.has(id))saved.delete(id);else saved.add(id);try{localStorage.setItem(favoriteStorageKey,JSON.stringify([...saved]));}catch{toast('This browser can’t keep an offline favorites copy.');}window.dispatchEvent(new CustomEvent('coreys:favorite-change',{detail:{id,selected:saved.has(id)}}));render();if(current)updateFavoriteButton();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200);}
function render(){const filtered=recipes.filter(r=>(category==='All recipes'||r.category===category)&&(cuisine==='All cuisines'||(cuisineById[r.id] || 'General & Everyday')===cuisine)&&(!onlyFav||saved.has(r.id))&&(!query||[r.title,r.category,(cuisineById[r.id] || 'General & Everyday'),...r.lines].join(' ').toLowerCase().includes(query.toLowerCase())));if(sort==='collection'){const featured=Object.keys(recipePhotos);filtered.sort((a,b)=>{let ai=featured.indexOf(a.id),bi=featured.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi);});}if(sort==='az')filtered.sort((a,b)=>a.title.localeCompare(b.title));if(sort==='za')filtered.sort((a,b)=>b.title.localeCompare(a.title));$('#fav-count').textContent=saved.size;$('#favorites-filter').setAttribute('aria-pressed',onlyFav);$('#result-count').textContent=`${filtered.length} ${filtered.length===1?'recipe':'recipes'}${category==='All recipes'?' in the recipe box':' in '+category}${cuisine==='All cuisines'?'':' · '+cuisine}${onlyFav?' · your favorites':''}`;$('#empty').hidden=!!filtered.length;$('#reset').hidden=category==='All recipes'&&cuisine==='All cuisines'&&!query&&!onlyFav;$('#grid').innerHTML=filtered.map(r=>{const i=recipes.indexOf(r);return `<article class="card">${art(r,i)}<button class="card-open" data-open="${r.id}" aria-label="Open ${esc(r.title)}"></button><button class="save ${saved.has(r.id)?'saved':''}" data-save="${r.id}" aria-label="${saved.has(r.id)?'Remove':'Save'} ${esc(r.title)} ${saved.has(r.id)?'from':'to'} favorites" aria-pressed="${saved.has(r.id)}">${saved.has(r.id)?'♥':'♡'}</button><div class="card-copy"><span class="tag">${esc(r.category)}</span><span class="cuisine-tag">${esc((cuisineById[r.id] || 'General & Everyday'))}</span><h3>${esc(r.title)}</h3><div class="card-bottom"><span>${timeLabel(r)}</span><span class="card-arrow">↗</span></div></div></article>`;}).join('');document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRecipe(b.dataset.open));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>favorite(b.dataset.save));document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.setAttribute('aria-pressed',b.dataset.category===category);});}
function timeLabel(r){let s=r.lines.find(l=>/Prep:|Total:|Cook:|Bake:/.test(l));if(!s)return 'From Corey’s cookbook';let m=s.match(/(?:Total|Prep):\s*([^|]+)/);return m?esc(m[0].trim()).slice(0,58):'Open the recipe';}
function reset(){category='All recipes';cuisine='All cuisines';$('#cuisine-filter').value=cuisine;query='';onlyFav=false;$('#search').value='';render();}
function sections(lines){let groups=[],g={title:'',items:[]};for(const l of lines){if(headings.has(l)){if(g.items.length)groups.push(g);g={title:l,items:[]};}else g.items.push(l);}if(g.items.length)groups.push(g);return groups;}
function linkify(s){return esc(s).replace(/https?:\/\/[^\s<]+/g,url=>{let clean=url.replace(/[.,;]+$/,'');let trailing=url.slice(clean.length);return `<a href="${clean}" target="_blank" rel="noopener noreferrer">${clean}</a>${trailing}`;});}
function openRecipe(id,fromHash=false){const r=recipes.find(r=>r.id===id);if(!r)return;current=r;serving='original';renderRecipe();window.coreysTrackRecipe?.(r);if(!$('#recipe-dialog').open)$('#recipe-dialog').showModal();document.body.style.overflow='hidden';if(!fromHash)history.replaceState(null,'','#'+r.id);$('#recipe-dialog').scrollTop=0;}
function renderRecipe(){const lines=window.coreysScale?window.coreysScale.lines(current,serving):(serving==='original'?current.lines:current.versions[serving]),groups=sections(lines),isBatch=false;$('#recipe-category').textContent=current.category+' · '+cuisineById[current.id];let html=`<h2 id="recipe-title">${esc(current.title)}</h2>${recipePhotos[current.id]?`<figure class="recipe-photo"><img src="${recipePhotos[current.id]}.${Number(current.id.slice(7)) >= 172 && Number(current.id.slice(7)) <= 177 ? 'svg?v=party-dips-1' : current.id === 'recipe-139' ? 'svg' : current.id === 'recipe-137' ? 'svg' : current.id === 'recipe-136' ? 'svg?v=693dcbb' : 'webp'}" alt="Illustrative serving suggestion for ${esc(current.title)}" width="1200" height="800"><figcaption>AI-generated serving suggestion. Your finished dish may look different.</figcaption></figure>`:''}<div class="recipe-actions"><button id="modal-favorite"></button><button id="share-recipe" type="button">Share recipe</button><button id="recipe-shopping" type="button">Add all to shopping list</button><button id="recipe-shopping-selected" type="button">Add selected items</button><button id="recipe-shopping-open" type="button">View shopping list</button><button id="print-recipe">Print recipe ↗</button></div><div class="servings" aria-label="Choose serving size"><span>AT THE TABLE</span>${(window.coreysScale?window.coreysScale.options(current):['original','1','2','3','4','5'].map(value=>({value,label:value}))).map(option=>{const s=option.value;return `<button data-serving="${s}" class="${serving===s?'active':''}" aria-pressed="${serving===s}">${esc(option.label)}</button>`;}).join('')}</div>${window.coreysScale?`<p class="batch-notice scale-note">${esc(window.coreysScale.note(current,serving))}</p>`:''}${isBatch?'<p class="batch-notice">Practical batch: this recipe keeps its normal batch size. Use the serving size listed below.</p>':''}<div class="recipe-sections">`;
for(const g of groups){const ingredient=/ingredient|spice blend/i.test(g.title),directions=/^directions$|^instructions$|^method$/i.test(g.title),source=/source/i.test(g.title);if(!g.title){html+=`<div class="recipe-meta recipe-section full">${g.items.map(s=>`<p>${esc(s)}</p>`).join('')}</div>`;continue;}html+=`<section class="recipe-section ${ingredient?'ingredients':directions?'directions':'full'} ${source?'sources':''}"><h3>${esc(g.title)}</h3>`;if(ingredient)html+='<ul>'+g.items.map(s=>`<li><label class="ingredient-check"><input type="checkbox" data-shopping-item="${esc(s)}"><span>${esc(s)}</span></label></li>`).join('')+'</ul>';else if(directions)html+='<ol>'+g.items.map(s=>`<li>${esc(s)}</li>`).join('')+'</ol>';else html+=g.items.map(s=>source?`<p>${linkify(s)}</p>`:`<p>${esc(s)}</p>`).join('');html+='</section>';}
html+='</div><p class="source-note">Check the ingredients you need, then tap “Add selected items” to put only those on your shopping list. Or tap “Add all to shopping list” for everything. From Corey’s Recipe Collection. Serving choices calculate ingredients from the original recipe yield. Cooking times are not multiplied. Check the source notes for attribution. Your ingredient checkmarks reset when you change servings.</p>';$('#recipe-content').innerHTML=html;updateFavoriteButton();$('#modal-favorite').onclick=()=>favorite(current.id);$('#share-recipe').onclick=()=>shareRecipe(current);$('#print-recipe').onclick=()=>window.print();$('#recipe-shopping-open').onclick=()=>window.coreysShopping.open();$('#recipe-shopping').onclick=()=>{const r=current,amount=serving,label=window.coreysScale.options(r).find(x=>x.value===amount)?.label||'Original batch';window.coreysShopping.addRecipe({recipeId:r.id,title:r.title+' · '+label,items:window.coreysScale.ingredients(window.coreysScale.lines(r,amount))});window.coreysShopping.open();};$('#recipe-shopping-selected').onclick=()=>{const selected=[...document.querySelectorAll('.recipe-section.ingredients input[data-shopping-item]:checked')];if(!selected.length){toast('Check the ingredients you need first');return;}const label=window.coreysScale.options(current).find(x=>x.value===serving)?.label||'Original batch';const all=window.coreysScale.ingredients(window.coreysScale.lines(current,serving));selected.forEach(input=>{const text=input.dataset.shoppingItem;window.coreysShopping.addIngredient({recipeId:current.id,title:current.title+' · '+label,text,index:all.indexOf(text)});});toast(selected.length+' ingredient'+(selected.length===1?'':'s')+' added to your shopping list');};document.querySelectorAll('[data-serving]').forEach(b=>b.onclick=()=>{serving=b.dataset.serving;renderRecipe();});}
function updateFavoriteButton(){const b=$('#modal-favorite');if(b){b.textContent=saved.has(current.id)?'♥ Saved to favorites':'♡ Save to favorites';b.setAttribute('aria-pressed',saved.has(current.id));}}
function closeRecipe(){if($('#recipe-dialog').open)$('#recipe-dialog').close();document.body.style.overflow='';current=null;if(location.hash.startsWith('#recipe-'))history.replaceState(null,'',location.pathname+location.search+'#recipes');}
$('#close-dialog').onclick=closeRecipe;$('#recipe-dialog').addEventListener('cancel',e=>{e.preventDefault();closeRecipe();});$('#recipe-dialog').addEventListener('click',e=>{if(e.target===$('#recipe-dialog')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeRecipe();}});$('#search').oninput=e=>{query=e.target.value;render();};$('#sort').onchange=e=>{sort=e.target.value;render();};$('#favorites-filter').onclick=()=>{onlyFav=!onlyFav;render();};$('#nav-favorites').onclick=()=>{onlyFav=true;category='All recipes';query='';$('#search').value='';render();$('#recipes').scrollIntoView();};$('#reset').onclick=reset;$('#empty-reset').onclick=reset;document.addEventListener('keydown',e=>{if(e.key==='/'&&!$('#recipe-dialog').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus();}});

// A fixed rotation keeps collection additions from changing an existing day's pick.
// Extend this schedule only at the end of a completed rotation.
const dailyRecipeIds=Array.from({length:131},(_,i)=>'recipe-'+(i+8));
const dailyHash=id=>{let h=2166136261;for(const c of id)h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0;};
dailyRecipeIds.sort((a,b)=>dailyHash(a)-dailyHash(b)||a.localeCompare(b));
function dailyRecipe(list, now=new Date()) {
  const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);
  const part=type=>parts.find(p=>p.type===type).value;
  const date=part('year')+'-'+part('month')+'-'+part('day');
  const day=Math.floor(Date.parse(date+'T12:00:00Z')/86400000);
  const id=dailyRecipeIds[((day%dailyRecipeIds.length)+dailyRecipeIds.length)%dailyRecipeIds.length];
  return {recipe:list.find(r=>r.id===id)||null,date};
}
let dailyTimer;
function renderDaily(now=new Date()) {
  clearTimeout(dailyTimer);
  const {recipe:r,date}=dailyRecipe(recipes,now);
  const feature=$('#daily-feature');
  dailyTimer=setTimeout(()=>renderDaily(),60000);
  if(feature.dataset.date===date&&feature.dataset.recipe===r?.id)return;
  if(!r){feature.hidden=true;return;}
  feature.hidden=false;feature.dataset.date=date;feature.dataset.recipe=r.id;
  $('#daily-title').textContent=r.title;
  $('#daily-date').textContent=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:'long',day:'numeric',year:'numeric'}).format(now);
  $('#daily-details').textContent=[(cuisineById[r.id] || 'General & Everyday'),r.category].filter(Boolean).join(' · ');
  $('#daily-photo').innerHTML=art(r,recipes.indexOf(r));
  const img=$('#daily-photo img');if(img){img.loading='eager';img.alt='Serving inspiration for '+r.title;}
  const button=$('#daily-open');button.setAttribute('aria-label','Open today’s recipe: '+r.title);button.onclick=()=>openRecipe(r.id);
  // Refresh an already-open page after midnight, without interrupting its recipe dialog.
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&recipes.length)renderDaily();});


// The account sync layer may replace the visible set without emitting a new save.
window.coreysFavoriteState={key:favoriteStorageKey,ready:()=>recipes.length>0,getIds:()=>[...saved],replace(ids){saved=new Set(ids.filter(id=>typeof id==='string'&&/^recipe-[1-9]\d{0,5}$/.test(id)));try{localStorage.setItem(favoriteStorageKey,JSON.stringify([...saved]));}catch{}if(recipes.length)render();if(current)updateFavoriteButton();},showFavorites(){reset();onlyFav=true;render();$('#recipes').scrollIntoView();}};
window.addEventListener('storage',e=>{if(!window.coreysCloud?.userId&&e.key===favoriteStorageKey){try{const ids=JSON.parse(e.newValue||'[]');if(Array.isArray(ids))window.coreysFavoriteState.replace(ids);}catch{}}});
Promise.all([fetch('recipes.json?v=rice-sauce').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('headings.json').then(r=>{if(!r.ok)throw Error();return r.json();})]).then(([data,hs])=>{recipes=[creamyChiliCrispPanSauce,zachGarlicParmesanHashBrowns,blenderBrazilianCheeseBread,bbcTwiceBakedPotatoes,airFryerWholeEggs,garlicButterBroccoliRotini,...curryCollection,karissaMacCheeseBurgers,arizonaBeansShirley,theasChickenAdobo,copycatBreadedWings,onePotMacCheese,cannedChickenNuggets,...freshSausageCollection,...novemberQuickMeals,pioneerMacaroniSalad,...mexicanTamales,...cajunPartySnacks,...homemadePartyDips,...homemadeSpiceBlends,yogurtBagels,bangBangSauce,chickenBologna,...chickenMarinades,creamyGarlicChicken,homemadeCreamCheese,homemadeCottageCheese,thaiCoconutCurry,masaCornChips,parmesanMeatballs,onionPasta,...cheesecakeBars,...pizzaSauces,...data.map(updateCreamer)];const pieTinIndex=recipes.findIndex(recipe=>recipe.id==='recipe-108');recipes.splice(pieTinIndex<0?recipes.length:pieTinIndex+1,0,cremaEnchiladas);headings=new Set(hs);renderDaily();const cuisines=['All cuisines',...new Set(recipes.map(r=>(cuisineById[r.id] || 'General & Everyday')))].sort((a,b)=>a==='All cuisines'?-1:b==='All cuisines'?1:a.localeCompare(b));$('#cuisine-filter').innerHTML=cuisines.map(c=>`<option>${esc(c)}</option>`).join('');$('#cuisine-filter').onchange=e=>{cuisine=e.target.value;render();};const cats=['All recipes',...new Set(recipes.map(r=>r.category))];$('#categories').innerHTML=cats.map(c=>`<button data-category="${esc(c)}" class="${c===category?'active':''}" aria-pressed="${c===category}">${esc(c)}</button>`).join('');document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render();});render();window.dispatchEvent(new Event('coreys:ready'));if(location.hash.startsWith('#recipe-'))openRecipe(location.hash.slice(1),true);}).catch(()=>{$('#result-count').textContent='The recipe box couldn’t load. Please refresh to try again.';$('#grid').innerHTML='<p>If this file was downloaded, serve the website through a web host rather than opening the HTML directly.</p>';});
async function shareRecipe(recipe){const url='https://corey-kite.github.io/coreys-kitchen/#'+recipe.id;try{await navigator.clipboard.writeText(url);toast('Recipe link copied');}catch{window.prompt('Copy this public recipe link:',url);}}
